def longest_word(words):
    if not words:
        return None
    return max(words, key=len)

def rotate_items(items, k):
    import operator

    k = operator.index(k)
    if k < 0:
        raise ValueError("k must be nonnegative")

    values = tuple(items)
    if not values:
        return None

    k %= len(values)
    return values[-k:] + values[:-k] if k else values

def interleave(left, right):
    if len(left) != len(right):
        raise ValueError("left and right must be equally sized")
    if len(left) == 0:
        return None
    result = []
    for left_item, right_item in zip(left, right):
        result.extend((left_item, right_item))
    return tuple(result)

def sort_labels(labels):
    items = tuple(labels)
    if not items:
        return None
    return tuple(sorted(dict.fromkeys(items)))

def find_products(products, query):
    if not products:
        return None

    folded_query = query.casefold()
    matches = [
        product for product in products
        if folded_query in product["name"].casefold()
    ]
    return tuple(sorted(matches, key=lambda product: product["score"], reverse=True))

def group_words(words):
    if not words:
        return None

    groups = []
    positions = {}

    for word in words:
        initial = word[0].casefold()
        if initial not in positions:
            positions[initial] = len(groups)
            groups.append((initial, []))
        groups[positions[initial]][1].append(word)

    return tuple((initial, tuple(group)) for initial, group in groups)

def parse_integer_fields(fields):
    if not fields:
        return None
    return tuple(int(field) for field in fields)

def nearest_date(dates, target):
    from datetime import date

    if not dates:
        return None

    target_date = date.fromisoformat(target)
    return min(
        dates,
        key=lambda value: abs((date.fromisoformat(value) - target_date).days),
    )

def median_value(values):
    if not values:
        return None
    ordered = sorted(values)
    middle = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2

def merge_ranges(ranges):
    if not ranges:
        return None

    ordered = sorted(ranges, key=lambda interval: interval[0])
    merged = []
    start, end = ordered[0]

    for next_start, next_end in ordered[1:]:
        if next_start <= end:
            end = max(end, next_end)
        else:
            merged.append((start, end))
            start, end = next_start, next_end

    merged.append((start, end))
    return tuple(merged)

def shortest_path(graph, start, goal):
    if not graph:
        return None

    if start not in graph or goal not in graph:
        return None

    if start == goal:
        return (start,)

    from collections import deque

    queue = deque([start])
    previous = {start: None}

    while queue:
        node = queue.popleft()

        for neighbor in graph[node]:
            if neighbor in previous:
                continue

            previous[neighbor] = node

            if neighbor == goal:
                path = []
                current = goal
                while current is not None:
                    path.append(current)
                    current = previous[current]
                path.reverse()
                return tuple(path)

            queue.append(neighbor)

    return ()

def topological_order(nodes, edges):
    import heapq

    nodes = tuple(nodes)
    if not nodes:
        return None

    index = {node: i for i, node in enumerate(nodes)}
    adjacency = {node: [] for node in nodes}
    indegree = {node: 0 for node in nodes}

    for source, destination in edges:
        adjacency[source].append(destination)
        indegree[destination] += 1

    ready = [i for i, node in enumerate(nodes) if indegree[node] == 0]
    heapq.heapify(ready)

    result = []
    while ready:
        node = nodes[heapq.heappop(ready)]
        result.append(node)
        for destination in adjacency[node]:
            indegree[destination] -= 1
            if indegree[destination] == 0:
                heapq.heappush(ready, index[destination])

    return tuple(result)
